-- kaya runtime for Haskell guests: loading, the direct-ring occurrence
-- loop, submit, and blob registration. Hand-written; the wire
-- vocabulary next to it
-- (KayaWire.hs) is generated by kaya-bindgen, and kaya_hs_stubs.c
-- carries the two ordered cursor accesses.
--
-- The direct tier: plain peeks on the ring's memory — GHC inlines them
-- to real loads — with ordering carried by the C stubs imported `ccall
-- unsafe` (GHC's own Addr# atomics are the wrong shape; see the stubs'
-- header). Blocking entries are `ccall safe`, releasing the capability
-- while C blocks; the -threaded runtime is required. Link against
-- libkaya at build time; kaya_run must own the process main thread, and
-- GHC's main runs bound to it.
module KayaRuntime
  ( kayaRun,
    kayaSubmit,
    pollOccurrence,
    waitOccurrences,
    wake,
    registerBlob,
    openPicked,
    UndoDelta (..),
    UndoText (..),
    UndoEntry (..),
    UndoOrder (..),
    emptyUndoDelta,
  )
where

import Data.Bits ((.&.))
import qualified Data.ByteString as BS
import Data.ByteString.Builder (Builder, toLazyByteString)
import qualified Data.ByteString.Lazy as BL
import Data.ByteString.Unsafe (unsafeUseAsCStringLen)
import Data.IORef (IORef, newIORef, readIORef, writeIORef)
import Data.Int (Int32, Int64)
import Data.Word (Word16, Word32, Word64, Word8)
import Foreign.C.Types (CBool (..), CSize (..))
import Foreign.Marshal.Alloc (alloca, mallocBytes)
import Foreign.Ptr (Ptr, castPtr, nullPtr, plusPtr)
import Foreign.Storable (peek, peekByteOff, poke)
import GHC.IO.Handle.FD (fdToHandle)
import System.IO (Handle)
import System.IO.Unsafe (unsafePerformIO)

import KayaWire
  ( ClipValues,
    Value (..),
    occKindRedone,
    occKindUndone,
    parseOccurrence,
    parseValue,
    specHash,
  )

foreign import ccall safe "kaya_run"
  c_kaya_run :: IO Int32

foreign import ccall safe "kaya_wake"
  c_kaya_wake :: IO ()

foreign import ccall unsafe "kaya_occurrence_ring"
  c_kaya_occurrence_ring :: Ptr () -> IO ()

-- | Redeem a picked handle: the OS handle lands in the first out-param
-- and seekability in the second; 0 is success.
--
-- SAFE, not unsafe: it BLOCKS, and may block for a long time — a cloud
-- provider can download the file before it answers — so the RTS must
-- keep running other threads while it does.
foreign import ccall safe "kaya_open_picked"
  c_kaya_open_picked :: Word64 -> Word32 -> Ptr Int64 -> Ptr Word32 -> IO Int32

foreign import ccall safe "kaya_wait_occurrences"
  c_kaya_wait_occurrences :: IO CBool

foreign import ccall unsafe "kaya_spec_hash"
  c_kaya_spec_hash :: IO Word64

foreign import ccall unsafe "kaya_submit"
  c_kaya_submit :: Ptr Word8 -> CSize -> IO ()

foreign import ccall unsafe "kaya_blob_register"
  c_kaya_blob_register :: Ptr Word8 -> CSize -> IO Word64

foreign import ccall unsafe "kaya_occurrence_blob"
  c_kaya_occurrence_blob :: Word64 -> Ptr CSize -> IO (Ptr Word8)

foreign import ccall unsafe "kaya_occurrence_blob_release"
  c_kaya_occurrence_blob_release :: Word64 -> IO ()

-- Redeem an occurrence blob for its bytes, and release it. Handed to
-- the generated decoder, never named by a guest.
--
-- COPY THEN RELEASE, in that order: the pointer borrows core memory
-- that the release frees. A blob arriving in an OCCURRENCE is a handle
-- into a table with no boundary that retires one — unlike the apply
-- channel's batch-local index, which the next batch supersedes — so the
-- decoder is what has to let go of it, while decoding, before any
-- handle can reach an app. Release is idempotent, so a dead handle
-- costs nothing rather than being an error the decoder must reason
-- about.
occurrenceBlob :: Word64 -> IO BS.ByteString
occurrenceBlob handle =
  alloca $ \lenPtr -> do
    poke lenPtr 0
    dat <- c_kaya_occurrence_blob handle lenPtr
    len <- peek lenPtr
    out <-
      if dat == nullPtr || len == 0
        then return BS.empty
        else BS.packCStringLen (castPtr dat, fromIntegral len)
    c_kaya_occurrence_blob_release handle
    return out

-- The ordered cursor accesses; see kaya_hs_stubs.c.
foreign import ccall unsafe "kaya_hs_load_acquire_u32"
  loadAcquireU32 :: Ptr Word32 -> IO Word32

foreign import ccall unsafe "kaya_hs_store_release_u32"
  storeReleaseU32 :: Ptr Word32 -> Word32 -> IO ()

-- | Enter the core on the calling thread (which must be the process
-- main thread); returns the exit code when the app ends.
-- The stale-artifact guard: this binding was generated from one spec
-- revision; the loaded library must speak the same one.
checkSpec :: IO ()
checkSpec = do
  got <- c_kaya_spec_hash
  if got == specHash
    then return ()
    else
      error
        ("kaya: library speaks spec " ++ show got
           ++ ", this binding was generated from " ++ show specHash
           ++ " — rebuild the library or regenerate bindings")

kayaRun :: IO Int32
kayaRun = checkSpec >> c_kaya_run

-- | Submit one transaction: the concatenation of packed records (tx*
-- results from KayaWire), applied atomically.
kayaSubmit :: [Builder] -> IO ()
kayaSubmit records =
  unsafeUseAsCStringLen (BL.toStrict (toLazyByteString (mconcat records))) $
    \(p, len) -> c_kaya_submit (castPtr p) (fromIntegral len)

-- | Register bulk payload bytes (an encoded image) with the core: one
-- copy into core-owned memory, returning the u64 handle. The handle is
-- consumed by the next submit from this guest, referenced or not; the
-- caller's bytes are free to drop the moment this returns.
registerBlob :: BS.ByteString -> IO Word64
registerBlob bytes =
  unsafeUseAsCStringLen bytes $ \(p, len) ->
    c_kaya_blob_register (castPtr p) (fromIntegral len)

data Ring = Ring (Ptr Word8) Word32 (Ptr Word32) (Ptr Word32) Word32

{-# NOINLINE ringRef #-}
ringRef :: IORef (Maybe Ring)
ringRef = unsafePerformIO (newIORef Nothing)

ring :: IO Ring
ring = do
  cached <- readIORef ringRef
  case cached of
    Just r -> return r
    Nothing -> do
      -- KayaRingInfo, as declared in kaya.h:
      -- { u8 *data; u32 capacity; u32 *head; u32 *tail } — offsets
      -- 0/8/16/24.
      info <- mallocBytes 32
      c_kaya_occurrence_ring info
      dat <- peekByteOff info 0 :: IO (Ptr Word8)
      capacity <- peekByteOff info 8 :: IO Word32
      headPtr <- peekByteOff info 16 :: IO (Ptr Word32)
      tailPtr <- peekByteOff info 24 :: IO (Ptr Word32)
      h0 <- loadAcquireU32 headPtr
      let r = Ring dat capacity headPtr tailPtr h0
      writeIORef ringRef (Just r)
      return r

-- | Block for the next occurrence; Nothing when the core has shut
-- down. Keys are [] when the id is a widget id, else the id is a
-- template node id and the keys are the stamped copy's key path,
-- outermost first; the last member is the payload — the entry's new
-- text (a VStr) for text_changed, the checkbox's new state (a VBool)
-- for toggled. Single consumer.
-- Return the app thread from waitOccurrences. Safe from any thread;
-- the binding calls it from KayaApp\'s post, and guests do not name it.
wake :: IO ()
wake = c_kaya_wake

-- Block until there MAY be something to do: a record arrived, or
-- another thread called wake. False once the core has shut down.
-- "May" is the honest word — a wake returns True with the ring still
-- empty, and the caller re-checks both sources, which a drain-then-poll
-- loop does anyway.
waitOccurrences :: IO Bool
waitOccurrences = do
  more <- c_kaya_wait_occurrences
  return (more /= CBool 0)

-- | What an undo or a redo PUT BACK: the core-authoritative statement
-- of the restored state (docs/undo-plan.md D5).
--
-- A STATEMENT, NOT A REPLAY. Every member says what a thing now IS, so
-- applying one twice is the same as applying it once and no reader
-- diffs anything of its own. Ids are raw — the newtypes over them
-- ('Widget', 'Signal') carry no Eq, so wrapping would buy a guest
-- nothing it could use.
data UndoDelta = UndoDelta
  { -- | Signal id -> its restored value.
    undoSignals :: ![(Word64, Value)],
    -- | The text fields this step put back, each NAMING itself. A
    -- coarse episode restore is a programmatic write, so nothing else
    -- would ever tell an app that folds text_changed into its own
    -- model.
    undoTexts :: ![UndoText],
    -- | Collection entries, present or gone.
    undoEntries :: ![UndoEntry],
    -- | Instance orders, for the instances whose order the step moved
    -- — position is the one thing per-entry statements cannot carry.
    undoOrders :: ![UndoOrder]
  }

-- | One text field's restored text, and the identity that names it.
--
-- TWO IDENTITIES, ONE RECORD, decided by the path — the vocabulary a
-- click or a paste on a stamped copy already arrives under. An EMPTY
-- 'utPath' means 'utId' is a live widget's id, the one the app holds;
-- a non-empty one means 'utId' is the TEMPLATE NODE and the path is
-- the copy's keys, outermost first, which is the only way a row's
-- field can be named at all (docs\/undo-plan.md §3b).
data UndoText = UndoText
  { utId :: !Word64,
    utPath :: ![Value],
    utText :: !String
  }

-- | One collection entry's restored state; 'ueState' is Nothing when
-- the restored state does not have this entry at all.
data UndoEntry = UndoEntry
  { ueCollection :: !Word64,
    uePath :: ![Value],
    ueKey :: !Value,
    ueState :: !(Maybe (Word32, [Value]))
  }

-- | One collection instance's restored key order.
data UndoOrder = UndoOrder
  { uoCollection :: !Word64,
    uoPath :: ![Value],
    uoKeys :: ![Value]
  }

-- | The empty statement: an occurrence carrying nothing back.
emptyUndoDelta :: UndoDelta
emptyUndoDelta = UndoDelta [] [] [] []

-- Decode an undone\/redone record: u64 window, the four run counts,
-- the Str label, then ONE flat value list read as those four runs in
-- order (kaya.h, KAYA_OCCURRENCE_UNDONE; crates\/kaya\/src\/wire.rs
-- undo_body).
--
-- HAND-WRITTEN BESIDE A GENERATED PARSER, and deliberately so: this
-- record's body is four COUNTED RUNS, which the generated
-- parseOccurrence's one shape (kind, id, keys, payload, clip) has
-- nowhere to put — the same reason the picker's three-values-per-file
-- are regrouped a tier up. Malformed input is a broken encoder rather
-- than bad data, so every case that cannot happen fails loudly.
parseUndo :: Ptr Word8 -> IO (Word64, String, UndoDelta)
parseUndo rec = do
  window <- peekByteOff rec 8 :: IO Word64
  signals <- peekByteOff rec 16 :: IO Word32
  texts <- peekByteOff rec 20 :: IO Word32
  entries <- peekByteOff rec 24 :: IO Word32
  orders <- peekByteOff rec 28 :: IO Word32
  (labelValue, afterLabel) <- parseValue rec 32
  count <- peekByteOff rec afterLabel :: IO Word32
  let readValues 0 _ acc = return (reverse acc)
      readValues n at acc = do
        (v, next) <- parseValue rec at
        readValues (n - 1 :: Word32) next (v : acc)
  -- The Values block's own header is {u32 count, u32 reserved}.
  flat <- readValues count (afterLabel + 8) []
  let label = case labelValue of
        VStr s -> s
        other -> error ("kaya: undo label is " ++ show other ++ ", wanted a string")
      int (VI64 n) = n
      int other = error ("kaya: undo delta wanted an integer, got " ++ show other)
      -- Each run consumes its own prefix and hands the rest on: a
      -- reader that stopped short would silently read the NEXT run's
      -- values as its own, so the leftover is checked at the end.
      takeRun 0 rest acc _ = (reverse acc, rest)
      takeRun n rest acc step = case step rest of
        (one, rest') -> takeRun (n - 1 :: Word32) rest' (one : acc) step
      pair (i : v : rest) = ((fromIntegral (int i) :: Word64, v), rest)
      pair _ = error "kaya: undo delta is truncated"
      -- ARITY-FIRST: size counts ITSELF, so a reader takes the head it
      -- knows and then `size` decides the rest — no schema, and a run
      -- that grows a field cannot silently eat the next one. This run
      -- joined the shape its two siblings below already had, because
      -- the fixed (id, text) pair it used to be had nowhere to put the
      -- path that names a stamped copy's field.
      text (size : ident : pathLen : rest) =
        let body = fromIntegral (int size) - 3
            (mine, rest') = splitAt body rest
            plen = fromIntegral (int pathLen)
            (path, textOnly) = splitAt plen mine
         in case textOnly of
              [VStr s] -> (UndoText (fromIntegral (int ident)) path s, rest')
              _ -> error "kaya: undo text is truncated or not a string"
      text _ = error "kaya: undo text is truncated"
      entry (size : collection : present : variant : pathLen : rest) =
        let body = fromIntegral (int size) - 5
            (mine, rest') = splitAt body rest
            plen = fromIntegral (int pathLen)
            (path, keyAndRecord) = splitAt plen mine
         in case keyAndRecord of
              (key : record) ->
                ( UndoEntry
                    (fromIntegral (int collection))
                    path
                    key
                    ( if int present /= 0
                        then Just (fromIntegral (int variant), record)
                        else Nothing
                    ),
                  rest'
                )
              [] -> error "kaya: undo entry has no key"
      entry _ = error "kaya: undo entry is truncated"
      order (size : collection : pathLen : rest) =
        let body = fromIntegral (int size) - 3
            (mine, rest') = splitAt body rest
            plen = fromIntegral (int pathLen)
            (path, keys) = splitAt plen mine
         in (UndoOrder (fromIntegral (int collection)) path keys, rest')
      order _ = error "kaya: undo order is truncated"
      (signalRun, afterSignals) = takeRun signals flat [] pair
      (textRun, afterTexts) = takeRun texts afterSignals [] text
      (entryRun, afterEntries) = takeRun entries afterTexts [] entry
      (orderRun, leftover) = takeRun orders afterEntries [] order
  if null leftover
    then return (window, label, UndoDelta signalRun textRun entryRun orderRun)
    else error "kaya: undo delta has trailing values"

-- Read the next occurrence if one is ready, WITHOUT blocking; Nothing
-- means the ring is empty right now.
--
-- Polling and waiting are separate actions, rather than one blocking
-- nextOccurrence, because the app thread has a SECOND source of work:
-- actions posted from other threads. A single blocking read would park
-- inside C with no way back out to run them.
--
-- The undo pair rides the same tuple as everything else: the window in
-- the id slot (the section_selected precedent), the label as the
-- payload, and the restored state in the last member.
pollOccurrence ::
  IO (Maybe (Word16, Word64, [Value], Maybe Value, Maybe ClipValues, Maybe UndoDelta))
pollOccurrence = do
  Ring dat capacity headPtr tailPtr h <- ring
  let mask = capacity - 1
      loop hh = do
        t <- loadAcquireU32 tailPtr -- acquire: records below are visible
        if hh == t
          then return Nothing -- nothing ready; the caller waits
          else do
            let at = fromIntegral (hh .&. mask)
            size <- peekByteOff dat at :: IO Word32
            kind <- peekByteOff dat (at + 4) :: IO Word16
            parsed <-
              if kind == occKindUndone || kind == occKindRedone
                then do
                  (w, label, delta) <- parseUndo (dat `plusPtr` at)
                  return (Just (kind, w, [], Just (VStr label), Nothing, Just delta))
                else do
                  ordinary <- parseOccurrence occurrenceBlob (dat `plusPtr` at)
                  return
                    ( fmap
                        (\(k, ident, keys, payload, clip) -> (k, ident, keys, payload, clip, Nothing))
                        ordinary
                    )
            -- Word32 wraps on its own; hand the space back with release.
            let hh' = hh + size
            storeReleaseU32 headPtr hh'
            cached <- readIORef ringRef
            case cached of
              Just (Ring d c hp tp _) ->
                writeIORef ringRef (Just (Ring d c hp tp hh'))
              Nothing -> return ()
            case parsed of
              Just occ -> return (Just occ)
              Nothing -> loop hh'
  loop h

-- | Redeem a picked handle for a real 'Handle', plus whether it seeks.
--
-- BLOCKS, and may block for a long time, so call it from a thread you
-- chose and post the result back (DESIGN.md, File dialogs).
--
-- THE DESCRIPTOR BECOMES GHC'S: 'fdToHandle' takes it over, so
-- 'hClose' closes it exactly once and the core keeps no claim.
--
-- Seekable rides the OPEN rather than the pick because that is the only
-- place the answer exists: an Android provider may hand back a pipe,
-- and nothing short of opening reveals it.
openPicked :: Word64 -> Word32 -> IO (Handle, Bool)
openPicked handle mode =
  alloca $ \rawPtr -> alloca $ \seekPtr -> do
    rc <- c_kaya_open_picked handle mode rawPtr seekPtr
    if rc /= 0
      then
        ioError
          (userError ("kaya: opening the picked file failed (code " ++ show rc ++ ")"))
      else do
        raw <- peek rawPtr
        seekable <- peek seekPtr
        h <- fdToHandle (fromIntegral raw)
        return (h, seekable /= 0)
